(7263001, 1129843, 35804, '<td valign="top">...blimp...I love it.</td>', '...blimp...I love it.', '2014-09-15 01:09:22.000000', NULL, 1),
(7263036, 1129872, 40391, '<td valign="top">That face! Wonderful.</td>', 'That face! Wonderful.', '2014-09-15 04:38:10.000000', NULL, 1),
(7263046, 1129789, 153814, '<td valign="top">This is outstanding. It looks like a wave about to break over the trees.<br/>My only 10.</td>', 'This is outstanding. It looks like a wave about to break over the trees.My only 10.', '2014-09-15 08:03:59.000000', NULL, 1),
(7263047, 1129848, 153814, '<td valign="top">Great job on this the sky looks as if it''s moving.<br/>Only knock is the stadium looks a bit tilted to the right oh and you can''t forget to give it a title. Still good enough for an 8 from me.</td>', 'Great job on this the sky looks as if it''s moving.Only knock is the stadium looks a bit tilted to the right oh and you can''t forget to give it a title. Still good enough for an 8 from me.', '2014-09-15 08:07:36.000000', NULL, 1),
(7263050, 1129812, 153814, '<td valign="top">Looks a tad over sharpened BUT to pull off a beautiful BW in this challenge is amazing. Heck of a job. Gutsy call going with the BW I gave it an 8.<br/>Well done.</td>', 'Looks a tad over sharpened BUT to pull off a beautiful BW in this challenge is amazing. Heck of a job. Gutsy call going with the BW I gave it an 8.Well done.', '2014-09-15 08:10:28.000000', NULL, 1),
(7263052, 1129791, 153814, '<td valign="top">So much to see in this shot. Very well done.</td>', 'So much to see in this shot. Very well done.', '2014-09-15 08:12:18.000000', NULL, 1),
(7263053, 1129665, 153814, '<td valign="top">Looks like a painting what a great shot.<br/>Well done.</td>', 'Looks like a painting what a great shot.Well done.', '2014-09-15 08:13:05.000000', NULL, 1),
(7263054, 1129718, 153814, '<td valign="top">The reflection is as interesting as the sky. Great job on this.</td>', 'The reflection is as interesting as the sky. Great job on this.', '2014-09-15 08:14:03.000000', NULL, 1),
(7263055, 1129717, 153814, '<td valign="top">Looks like the sky is being split in half. Very well done.</td>', 'Looks like the sky is being split in half. Very well done.', '2014-09-15 08:15:02.000000', NULL, 1),
(7263057, 1129869, 153814, '<td valign="top">I can almost hear the silence. Well done, not over sharpened and you did a great job capturing the sky fading from blue to orange. One of my top picks.</td>', 'I can almost hear the silence. Well done, not over sharpened and you did a great job capturing the sky fading from blue to orange. One of my top picks.', '2014-09-15 08:17:41.000000', NULL, 1),
(7263059, 1129792, 153814, '<td valign="top">Back for a second look already, great contrast and very interesting sky.<br/>Had to bump this up a bit. Well done.</td>', 'Back for a second look already, great contrast and very interesting sky.Had to bump this up a bit. Well done.', '2014-09-15 08:19:46.000000', NULL, 1),
(7263063, 1129803, 153814, '<td valign="top">Well executed image. The colors of the sky are amazing I just wish you had more sky and less rock. The sky is MUCH more interesting.</td>', 'Well executed image. The colors of the sky are amazing I just wish you had more sky and less rock. The sky is MUCH more interesting.', '2014-09-15 08:23:09.000000', NULL, 1),
(7263068, 1129741, 153814, '<td valign="top">Very calming image the bird is a nice touch. I really like the sun rays.<br/>The sky looks a bit grainy but overall this is very nice. Well done.</td>', 'Very calming image the bird is a nice touch. I really like the sun rays.The sky looks a bit grainy but overall this is very nice. Well done.', '2014-09-15 08:26:14.000000', NULL, 1),
(7263073, 1129777, 153814, '<td valign="top">Great transition from light to dark. The landscape silhouette adds a nice contrast. Well done.</td>', 'Great transition from light to dark. The landscape silhouette adds a nice contrast. Well done.', '2014-09-15 08:29:43.000000', NULL, 1),
(7263074, 1129818, 153814, '<td valign="top">That''s one nasty looking sky. Well done. Gutsy going with a BW but it worked.<br/>Nice job.</td>', 'That''s one nasty looking sky. Well done. Gutsy going with a BW but it worked.Nice job.', '2014-09-15 08:31:18.000000', NULL, 1),
(7263075, 1129577, 153814, '<td valign="top">Looks like the cover of a book. Nice job.</td>', 'Looks like the cover of a book. Nice job.', '2014-09-15 08:32:12.000000', NULL, 1),
(7263077, 1129824, 153814, '<td valign="top">Great mix of colors here. Well done.</td>', 'Great mix of colors here. Well done.', '2014-09-15 08:33:09.000000', NULL, 1),
(7263080, 1129684, 153814, '<td valign="top">Nice shot the colors of the rays are beautiful but overall the image is a bit dark. Very different from the rest in a good way.</td>', 'Nice shot the colors of the rays are beautiful but overall the image is a bit dark. Very different from the rest in a good way.', '2014-09-15 08:35:27.000000', NULL, 1),
