INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7264847, 1129867, 149964, '<td valign="top">Love the drama in this.</td>', 'Love the drama in this.', '2014-09-21 16:59:06.000000', NULL, 1),
(7264848, 1129880, 149964, '<td valign="top">Surprised at how many colours there are in this! Especially the red - are these satellites???</td>', 'Surprised at how many colours there are in this! Especially the red - are these satellites???', '2014-09-21 16:59:58.000000', NULL, 1),
(7264849, 1129744, 149964, '<td valign="top">Clever use of cropsprayer to provide a ''third'' without detracting from the sky</td>', 'Clever use of cropsprayer to provide a ''third'' without detracting from the sky', '2014-09-21 17:00:45.000000', NULL, 1),
(7264850, 1129848, 149964, '<td valign="top">Something apocalyptic about this! Love the way the dramatic sky has been captured</td>', 'Something apocalyptic about this! Love the way the dramatic sky has been captured', '2014-09-21 17:01:16.000000', NULL, 1),
(7264851, 1129774, 149964, '<td valign="top">Love how youve captured the orange tinges.</td>', 'Love how youve captured the orange tinges.', '2014-09-21 17:01:52.000000', NULL, 1),
(7264852, 1129881, 149964, '<td valign="top">I like the way the mountanis are sharp against the soft sky.</td>', 'I like the way the mountanis are sharp against the soft sky.', '2014-09-21 17:02:57.000000', NULL, 1),
(7264853, 1129854, 149964, '<td valign="top">Clever silhouetting of the birds against what looks like a stormy sky.</td>', 'Clever silhouetting of the birds against what looks like a stormy sky.', '2014-09-21 17:03:41.000000', NULL, 1),
(7264854, 1129718, 149964, '<td valign="top">Beautiful. I was wondering what it might have looked like if the land horizon had been centralsied. I think I might have liked to have seen more of the lovely sky reflected.</td>', 'Beautiful. I was wondering what it might have looked like if the land horizon had been centralsied. I think I might have liked to have seen more of the lovely sky reflected.', '2014-09-21 17:05:10.000000', NULL, 1),
(7264855, 1129727, 149964, '<td valign="top">Clever iuse of an object to higl;ight (and reflect) the sky.</td>', 'Clever iuse of an object to higl;ight (and reflect) the sky.', '2014-09-21 17:05:42.000000', NULL, 1),
(7264856, 1129717, 149964, '<td valign="top">Jealous. I have AuroraWatch on Twitter to see if I can try and catch this! Not helped by living in Southern England! This is a lovely capture.</td>', 'Jealous. I have AuroraWatch on Twitter to see if I can try and catch this! Not helped by living in Southern England! This is a lovely capture.', '2014-09-21 17:06:36.000000', NULL, 1),
(7264857, 1129878, 149964, '<td valign="top">Clever way to provide a focus without losing the theme of the challenge.</td>', 'Clever way to provide a focus without losing the theme of the challenge.', '2014-09-21 17:07:38.000000', NULL, 1),
(7264858, 1129818, 149964, '<td valign="top">I like the use of the solar panel to break up the scene withoutr detracting from the dramatic sky.</td>', 'I like the use of the solar panel to break up the scene withoutr detracting from the dramatic sky.', '2014-09-21 17:08:38.000000', NULL, 1),
(7264859, 1129789, 149964, '<td valign="top">Looks like the sky is reflecting a fire in the forest.Simple but effective colours.</td>', 'Looks like the sky is reflecting a fire in the forest.Simple but effective colours.', '2014-09-21 17:09:32.000000', NULL, 1),
(7264860, 1129841, 149964, '<td valign="top">Clever use of lines to break up the sky without detracting from it.</td>', 'Clever use of lines to break up the sky without detracting from it.', '2014-09-21 17:09:59.000000', NULL, 1),
(7264861, 1129791, 149964, '<td valign="top">Beautiful. Gerat sky and love the way the yellow/orange tinges the clouds.</td>', 'Beautiful. Gerat sky and love the way the yellow/orange tinges the clouds.', '2014-09-21 17:10:26.000000', NULL, 1),
(7264862, 1129849, 149964, '<td valign="top">A greta shot but strikes me as more fo a landscape than a skyscape.</td>', 'A greta shot but strikes me as more fo a landscape than a skyscape.', '2014-09-21 17:11:01.000000', NULL, 1),
(7264863, 1129475, 149964, '<td valign="top">A beautiful shot of the moon but I would have preferred it without the extra lightspot.</td>', 'A beautiful shot of the moon but I would have preferred it without the extra lightspot.', '2014-09-21 17:11:39.000000', NULL, 1),
(7264864, 1129812, 149964, '<td valign="top">Lovely dramatic sky with subtle use of landscape to accentuate it.</td>', 'Lovely dramatic sky with subtle use of landscape to accentuate it.', '2014-09-21 17:12:11.000000', NULL, 1),
(7264865, 1129573, 149964, '<td valign="top">Clever :-)</td>', 'Clever :-)', '2014-09-21 17:13:04.000000', NULL, 1),
