(7264884, 1129665, 124982, '<td valign="top">Not a big fan of the HDR tone mapping in this one, as I feel the image could use some more dramatic blacks/shadows to compliment the clouds. Still, a great image nonetheless/</td>', 'Not a big fan of the HDR tone mapping in this one, as I feel the image could use some more dramatic blacks/shadows to compliment the clouds. Still, a great image nonetheless/', '2014-09-21 19:12:19.000000', NULL, 1),
(7264885, 1129872, 124982, '<td valign="top">Totally see a face in the clouds! Creepy indeed!</td>', 'Totally see a face in the clouds! Creepy indeed!', '2014-09-21 19:13:47.000000', NULL, 1),
(7264886, 1129867, 124982, '<td valign="top">Quite gorgeous! Love the black and white effect, very painterly!</td>', 'Quite gorgeous! Love the black and white effect, very painterly!', '2014-09-21 19:15:16.000000', NULL, 1),
(7264901, 1129789, 124982, '<td valign="top">Quite spectacular lighting. Exceptionally powerful (and ominous) image.</td>', 'Quite spectacular lighting. Exceptionally powerful (and ominous) image.', '2014-09-21 20:33:16.000000', NULL, 1),
