(7265106, 1129791, 18505, '<td valign="top">Congratulations on your ribbon, Nancie.  I love the layers in the clouds and the lighting is breathtaking.</td>', 'Congratulations on your ribbon, Nancie.  I love the layers in the clouds and the lighting is breathtaking.', '2014-09-22 11:32:25.000000', NULL, 0),
